package org.aust.sms.data
import android.content.ContentResolver
import android.provider.Telephony
class SmsRepository(private val resolver:ContentResolver){fun loadMessages(limit:Int=500):List<SmsMessage>{val r=ArrayList<SmsMessage>(); val p=arrayOf(Telephony.Sms._ID,Telephony.Sms.THREAD_ID,Telephony.Sms.ADDRESS,Telephony.Sms.BODY,Telephony.Sms.DATE,Telephony.Sms.TYPE,Telephony.Sms.READ); resolver.query(Telephony.Sms.CONTENT_URI,p,null,null,"${Telephony.Sms.DATE} DESC LIMIT $limit")?.use{c->val i=c.getColumnIndexOrThrow(Telephony.Sms._ID);val t=c.getColumnIndexOrThrow(Telephony.Sms.THREAD_ID);val a=c.getColumnIndexOrThrow(Telephony.Sms.ADDRESS);val b=c.getColumnIndexOrThrow(Telephony.Sms.BODY);val d=c.getColumnIndexOrThrow(Telephony.Sms.DATE);val ty=c.getColumnIndexOrThrow(Telephony.Sms.TYPE);val rd=c.getColumnIndexOrThrow(Telephony.Sms.READ);while(c.moveToNext())r+=SmsMessage(c.getLong(i),c.getLong(t),c.getString(a)?:(""),c.getString(b)?:(""),c.getLong(d),c.getInt(ty),c.getInt(rd)!=0)};return r}}
